create or replace TABLE LDL_DATA_PRODUCTION.CORE_DIM.T_DIM_BUSINESS_YEAR_2 (
	BUS_YEAR NUMBER(38,0) NOT NULL COMMENT 'The business year as a number in the form YYYY. Eg. 2019',
	BUS_YEAR_BEGIN_MONTH NUMBER(38,0) NOT NULL COMMENT 'The first (calendar_2) month (inclusive) of the business year as a number in the form YYYYMM, i.e. the March of the year specified by the field bus_year. Eg. 201903 for 2019.',
	BUS_YEAR_END_MONTH NUMBER(38,0) NOT NULL COMMENT 'The last (calendar_2) month (inclusive) of the business year as a number in the form YYYYMM, i.e. the February of the year after that specified by the field bus_year.Eg. 202002 for 2019. ',
	BUS_YEAR_BEGIN_PART_WEEK NUMBER(38,0) NOT NULL COMMENT 'The first partial week (inclusive) of the business year as a number in the form YYYYWWn. Eg. 2019092.',
	BUS_YEAR_END_PART_WEEK NUMBER(38,0) NOT NULL COMMENT 'The last partial week (inclusive) of the business year as a number in the form YYYYWWn. Eg. 2020091.',
	BUS_YEAR_BEGIN_DT DATE NOT NULL COMMENT 'The first day (inclusive) of the business year as a conventional calendar_2 date in the form ''YYYY-MM_2-DD''. Eg. ''2019-03-01''.',
	BUS_YEAR_END_DT DATE NOT NULL COMMENT 'The first day (inclusive) of the business year as a conventional calendar_2 date in the form ''YYYY-MM_2-DD''. Eg. ''2020-02-29''. ',
	BUS_YEAR_WEEK_CNT NUMBER(38,0) COMMENT 'The number of weeks that this business year contains. (i,.e. 52 or 53) If a week spans two business years, it is counted for the year, in which it has at least four days.',
	BUS_YEAR_PART_WEEK_CNT NUMBER(38,0) COMMENT 'The number of partial weeks that this business year contains.',
	BUS_YEAR_DAY_CNT NUMBER(38,0) COMMENT 'The number of days that this business year contains. (i,.e. 365 or 366 for leap years)',
	LEAP_YEAR_FG BOOLEAN NOT NULL COMMENT 'An indicator showing, if this year is a leap year, i.e. if it has 366 days.',
	PREV_1Y_BUS_YEAR NUMBER(38,0) NOT NULL COMMENT 'The business year 1 year ago as a number in the form YYYY. E.g. 2018, if the current business year is 2019.',
	PREV_2Y_BUS_YEAR NUMBER(38,0) NOT NULL COMMENT 'The business year 2 years ago as a number in the form YYYY. Eg. 2017, if the current business year is 2019.',
	PREV_3Y_BUS_YEAR NUMBER(38,0) NOT NULL COMMENT 'The business year 3 years ago as a number in the form YYYY. Eg. 2016, if the current business year is 2019.',
	PREV_4Y_BUS_YEAR NUMBER(38,0) NOT NULL COMMENT 'The business year 4 years ago as a number in the form YYYY. Eg. 2015, if the current business year is 2019.',
	PREV_5Y_BUS_YEAR NUMBER(38,0) NOT NULL COMMENT 'The business year 5 years ago as a number in the form YYYY. Eg. 2014, if the current business year is 2019.',
	CURR_BUS_YEAR_FG BOOLEAN NOT NULL COMMENT 'This indicator is set for the current business year.',
	BUS_YEAR_OFFSET NUMBER(38,0) COMMENT 'The difference in years between this business year and the current business year. So if the current business year is 2019, then the offset is 0 for 2019, -1 for 2018 and +1 for 2020.  ',
	DWH_CREATED_TMSP TIMESTAMP_LTZ(9) NOT NULL COMMENT 'The point in time when this record was created in the data warehouse.',
	DWH_UPDATED_TMSP TIMESTAMP_LTZ(9) NOT NULL COMMENT 'The point in time when this record was created or last updated.',
	DWH_LOAD_ID NUMBER(38,0) NOT NULL COMMENT 'The unique identifier of the batch load which has done the last update to this record. (Closing a record in history without updating any payload columns does not trigger an update of the dwh_load_id.)',
	DWH_NODE_CD VARCHAR(20) NOT NULL COMMENT 'The code for the source system (or slice of source system) from which this record was loaded.',
	constraint PK_T_DIM_BUSINESS_YEAR primary key (BUS_YEAR)
)COMMENT='Lidl business years, starting in March and ending in February. Eg. Business Year 2019 is March 2019 to February 2020 inclusive.'
;